with base as (select *,row_number() over(partition by coalesce(nullif(lower(trim(email)),''),'anonymous:'||id::text) order by coalesce(updated_at,created_at) desc nulls last,id desc) as rn from public.pesquisa_implementacao_crms),latest as(select * from base where rn=1),dims as(select dim,valor,count(*)::int as n from latest cross join lateral(values ('area',area_atuacao),('porte',porte_empresa),('plataforma',plataforma_principal),('execucao',formato_execucao),('tempo',tempo_implementacao))d(dim,valor) group by dim,valor),bottlenecks as(select label,count(*)::int as n from latest cross join lateral(values ('Dados legados','Qualidade e organização dos dados legados do cliente'),('Customizações e integrações','Customizações complexas, códigos customizados e integrações via API'),('Processos e resistência interna','Alinhamento de processos e resistência interna da equipe do cliente'),('Escopo e requisitos','Escopo mal dimensionado / Falta de clareza nos requisitos de negócio'),('Outro','Outro')) b(label,needle) where strpos(coalesce(gargalos,''),needle)>0 group by label) select jsonb_build_object('total_bruto',(select count(*) from base),'total_consolidado',(select count(*) from latest),'primeira_resposta',(select min(created_at)::date from base),'ultima_resposta',(select max(created_at)::date from base),'vazios_email',(select count(*) from base where nullif(trim(email),'') is null),'dimensoes',(select jsonb_agg(to_jsonb(dims) order by dim,n desc,valor) from dims),'gargalos',(select jsonb_agg(to_jsonb(bottlenecks) order by n desc,label) from bottlenecks),'gargalos_respondidos',(select count(*) from latest where nullif(trim(gargalos),'') is not null)) as report;
